// dot4: 4-lane signed 8-bit dot product. Generated by the RTL agent.
// Architecture: latency 3, pipeline registers after: products, mult_mid.
module dot4 (
    input  logic               clk,
    input  logic               rst_n,
    input  logic               in_valid,
    input  logic        [31:0] a,
    input  logic        [31:0] b,
    output logic               out_valid,
    output logic signed [17:0] y
);
    localparam int LAT = 3;

    // input registers
    logic signed [7:0] ar [4], br [4];
    always_ff @(posedge clk)
        if (in_valid)
            for (int k = 0; k < 4; k++) begin
                ar[k] <= a[8*k +: 8];
                br[k] <= b[8*k +: 8];
            end

    // multipliers split in two: low and high nibble of b, registered in between
    logic signed [15:0] plo_d [4], phi_d [4];
    logic signed [15:0] plo [4], phi [4];
    always_comb
        for (int k = 0; k < 4; k++) begin
            plo_d[k] = 16'(ar[k]) * $signed({1'b0, br[k][3:0]});
            phi_d[k] = 16'(ar[k]) * 16'($signed(br[k][7:4]));
        end
    always_ff @(posedge clk)
        for (int k = 0; k < 4; k++) begin
            plo[k] <= plo_d[k];
            phi[k] <= phi_d[k];
        end
    logic signed [15:0] p [4];
    always_comb for (int k = 0; k < 4; k++) p[k] = plo[k] + (phi[k] <<< 4);

    // pipeline register after the multipliers
    logic signed [15:0] pq [4];
    always_ff @(posedge clk) for (int k = 0; k < 4; k++) pq[k] <= p[k];

    // balanced adder tree
    logic signed [16:0] s01, s23;
    assign s01 = 17'(pq[0]) + 17'(pq[1]);
    assign s23 = 17'(pq[2]) + 17'(pq[3]);

    // output register
    always_ff @(posedge clk)
        y <= 18'(s01) + 18'(s23);

    // valid pipeline: the only state that needs a reset
    logic [LAT:0] v;
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) v <= '0;
        else        v <= {v[LAT-1:0], in_valid};
    assign out_valid = v[LAT];
endmodule
